#!/usr/bin/env python3
"""Download the T-Drive data and expose its raw trajectory directory locally."""

from __future__ import annotations

import argparse
import shutil
import sys
from pathlib import Path

DATASET = "arashnic/tdriver"
REPO_ROOT = Path(__file__).resolve().parent.parent
DEFAULT_DESTINATION = REPO_ROOT / "taxi_log_2008_by_id"


def find_raw_directory(download_root: Path) -> Path | None:
    """Find the expected raw trajectory directory in a kagglehub download."""
    candidates = [
        download_root / "taxi_log_2008_by_id",
        download_root / "release" / "taxi_log_2008_by_id",
    ]
    candidates.extend(download_root.rglob("taxi_log_2008_by_id"))
    for candidate in candidates:
        if candidate.is_dir():
            return candidate
    return None


def materialize(source: Path, destination: Path, overwrite: bool) -> None:
    if destination.exists():
        if not overwrite:
            print(
                f"Destination already exists: {destination}\n"
                "Use --overwrite to replace it, or pass --destination for another location.",
                file=sys.stderr,
            )
            raise SystemExit(2)
        if destination.is_symlink() or destination.is_file():
            destination.unlink()
        else:
            shutil.rmtree(destination)

    destination.parent.mkdir(parents=True, exist_ok=True)
    shutil.copytree(source, destination)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Download T-Drive and copy raw <id>.txt trajectories into this checkout."
    )
    parser.add_argument(
        "--destination",
        type=Path,
        default=DEFAULT_DESTINATION,
        help=f"raw-data destination (default: {DEFAULT_DESTINATION})",
    )
    parser.add_argument(
        "--overwrite",
        action="store_true",
        help="replace an existing destination",
    )
    parser.add_argument(
        "--download-only",
        action="store_true",
        help="print the kagglehub cache path without copying data into the repository",
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    try:
        import kagglehub
    except ImportError:
        print("Missing dependency: install it with `python3 -m pip install kagglehub`.", file=sys.stderr)
        return 2

    try:
        download_root = Path(kagglehub.dataset_download(DATASET))
    except Exception as error:
        print(
            "Unable to download the T-Drive dataset. Configure Kaggle credentials, then retry.\n"
            f"Kagglehub error: {error}",
            file=sys.stderr,
        )
        return 1

    raw_directory = find_raw_directory(download_root)
    if raw_directory is None:
        print(
            f"Downloaded dataset did not contain taxi_log_2008_by_id under {download_root}.",
            file=sys.stderr,
        )
        return 1

    if args.download_only:
        print(raw_directory)
        return 0

    materialize(raw_directory, args.destination.resolve(), args.overwrite)
    file_count = sum(1 for _ in args.destination.glob("*.txt"))
    print(f"Copied {file_count} raw trajectories to {args.destination.resolve()}")
    print("Next: run `cmake --build build` and `./build/normalize --all`.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

